import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"最近更新","description":"","frontmatter":{},"headers":[],"relativePath":"guide/whats-new.md","filePath":"guide/whats-new.md"}'),o={name:"guide/whats-new.md"};function r(d,e,n,h,c,s){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="最近更新" tabindex="-1">最近更新 <a class="header-anchor" href="#最近更新" aria-label="Permalink to &quot;最近更新&quot;">​</a></h1><p>升级到最新版后就能用。员工端会自动升级；命令行 <code>flyknit</code> 和员工端装在一起，一起升级。</p><h2 id="_2026-年-11-月" tabindex="-1">2026 年 11 月 <a class="header-anchor" href="#_2026-年-11-月" aria-label="Permalink to &quot;2026 年 11 月&quot;">​</a></h2><h3 id="在命令行里直接对话" tabindex="-1">在命令行里直接对话 <a class="header-anchor" href="#在命令行里直接对话" aria-label="Permalink to &quot;在命令行里直接对话&quot;">​</a></h3><p>新开 cmd / PowerShell / Windows Terminal，进入文件夹输入 <code>flyknit</code>，就能像聊天窗口一样一句一句地交代：回答边生成边显示，每一步操作一行，需要确认的操作在命令行里问你（<code>y</code> 允许 / <code>a</code> 以后自动 / <code>n</code> 拒绝），<code>Ctrl+C</code> 停下当前这一轮。</p><p><code>flyknit -c</code> 接着上次的对话，<code>flyknit --resume</code> 挑一个以前的对话接着聊。→ <a href="/help/guide/terminal.html">终端对话</a></p><h3 id="flyknit-p-不再「半天没反应」" tabindex="-1">flyknit -p 不再「半天没反应」 <a class="header-anchor" href="#flyknit-p-不再「半天没反应」" aria-label="Permalink to &quot;flyknit -p 不再「半天没反应」&quot;">​</a></h3><p>在命令行里直接运行 <code>flyknit -p</code> 时，会边做边显示每一步在做什么，最后再输出结果；放在脚本里时输出不变。→ <a href="/help/guide/cli-and-ide.html">命令行脚本与 CI</a></p><h3 id="ide-里更快、能找回以前的会话" tabindex="-1">IDE 里更快、能找回以前的会话 <a class="header-anchor" href="#ide-里更快、能找回以前的会话" aria-label="Permalink to &quot;IDE 里更快、能找回以前的会话&quot;">​</a></h3><ul><li>关掉 VS Code 再打开，可以在插件的会话列表里找到以前的会话接着聊（命令行里也能 <code>/resume</code> 接着聊）。</li><li>回答和过程成段显示，不再一个字一个字地刷屏。</li><li>命令行和 IDE 默认不开深度思考，长任务明显更快；需要时加 <code>--think</code>。</li></ul><p>→ <a href="/help/guide/ide.html">在 IDE 里用</a></p><h3 id="回答里的-pr-链接显示成卡片" tabindex="-1">回答里的 PR 链接显示成卡片 <a class="header-anchor" href="#回答里的-pr-链接显示成卡片" aria-label="Permalink to &quot;回答里的 PR 链接显示成卡片&quot;">​</a></h3><p>开着开发者工具时，回答里的 GitHub PR / Issue 地址显示成带图标的「#123」，鼠标停上去弹出卡片：状态（开放 / 草稿 / 已合并 / 已关闭）、标题、作者、改了多少行。→ <a href="/help/guide/developer.html#聊天里的-pr-链接">开发者工具与 PR</a></p><h3 id="更省额度" tabindex="-1">更省额度 <a class="header-anchor" href="#更省额度" aria-label="Permalink to &quot;更省额度&quot;">​</a></h3><ul><li>长对话里，之前的内容可以被模型服务的缓存复用，每多聊一句要重新计费的部分少了很多。</li><li>读过的大文件、长命令输出会更早地精简，不会每一步都整段重发。</li><li>去掉了后台反复做的会话摘要。</li></ul><p>日常使用不用做任何设置。</p><h3 id="给管理员" tabindex="-1">给管理员 <a class="header-anchor" href="#给管理员" aria-label="Permalink to &quot;给管理员&quot;">​</a></h3><ul><li><strong>按部门隔离</strong>：技能、专家、连接器可以设「使用范围」，只给某些部门或某几台电脑用；范围外的电脑看不到、用不了。→ <a href="/help/admin/console.html#按部门隔离">管理后台一览</a></li><li><strong>按部门 / 单台电脑设置安全中心</strong>：比如只给研发部打开开发者工具、命令行 / IDE 接入；设备详情里能单独设置某一台。→ <a href="/help/admin/security-center.html">安全中心</a></li><li><strong>用量按用途看</strong>：仪表盘新增「按用途」，分开看正常对话和压缩上下文、任务复盘、整理记忆、生成标题这些后台调用各用了多少，以及模型服务的缓存命中率。→ <a href="/help/admin/console.html">管理后台一览</a></li></ul>',18)])])}const f=a(o,[["render",r]]);export{u as __pageData,f as default};
